export type SocialOAuthProvider = 'google' | 'azure' | 'github';

const providerLabels: Record<SocialOAuthProvider, string> = {
  google: 'Google',
  azure: 'Microsoft',
  github: 'GitHub',
};

export const socialOAuthProviderLabel = (provider: SocialOAuthProvider) => providerLabels[provider];

export const buildSocialOAuthOptions = (provider: SocialOAuthProvider, redirectTo: string) => ({
  redirectTo,
  ...(provider === 'azure'
    ? { scopes: 'email' }
    : provider === 'google'
      ? {
          queryParams: {
            access_type: 'offline',
            prompt: 'select_account',
          },
        }
      : {}),
});
